import json
import pprint

sensor_values = {
    "Sensor1": {"temp": 77.0, "hum": 40},
    "Sensor2": {"temp": 86.9, "hum": 50},
    "Sensor3": {"temp": 82.04, "hum": 45},
    "Sensor4": {"temp": 71.78, "hum": 55},
    "Sensor5": {"temp": 96.08, "hum": 60}
}

sensor_val_celsius = {}
for key, value in sensor_values.items():
    celsius = round((value["temp"] - 32) / 1.8, 3)
    sensor_val_celsius[key] = {"temp": celsius, "hum": value["hum"]}

with open("sensor_cels.json", "w") as fp:
    json.dump(sensor_val_celsius, fp, indent=4)

with open("sensor_cels.json", "r") as fp:
    my_read_dict = json.load(fp)

pprint.pprint(my_read_dict)
